INSERT INTO public.page_sections (page_id, section_key, data, sort_order) VALUES ((SELECT id FROM public.pages WHERE slug = 'inicio'), 'hero', '{"imagen_fondo":"Se sube desde el admin pero por ahora es fondo-hero.png","titulo":"Nuestro futuro no es desechable, *actuemos* ahora.","descripcion":"Recuperamos, transportamos y aprovechamos residuos sólidos en Suba, Engativá y Usaquén — devolviéndoles valor.","cta_texto":"Solicitar servicio","cta_url":"/solicitar"}'::jsonb, 0);
