INSERT INTO public.page_sections (page_id, section_key, data, sort_order) VALUES ((SELECT id FROM public.pages WHERE slug = 'nosotros'), 'hero', '{"imagen_fondo":"Se puede subir","titulo":"Somos quienes recuperan la ciudad","descripcion":"ASOFRAIN E.S.P. — una organización de recuperadores ambientales que presta el servicio público de aprovechamiento en Bogotá desde 2006.","cta_1_texto":"Conocer la historia","cta_1_url":"","cta_2_texto":"Ver aliados","cta_2_url":""}'::jsonb, 0);
INSERT INTO public.page_sections (page_id, section_key, data, sort_order) VALUES ((SELECT id FROM public.pages WHERE slug = 'nosotros'), 'quienes_somos', '{"titulo":"Una empresa pública, operada por sus recuperadores.","descripcion":"ASOFRAIN E.S.P. es una Empresa de Servicios Públicos constituida por recuperadores ambientales, reconocida ante la Superintendencia de Servicios Públicos Domiciliarios (SSPD) como prestadora del servicio público de aprovechamiento en Bogotá D.C. Operamos bajo el marco tarifario CRA 720 de 2015 y el Decreto 596 de 2016, con enfoque territorial en las localidades de Suba, Engativá y Usaquén. Nuestra razón de ser combina un servicio esencial para la ciudad con la dignificación laboral de las familias recuperadoras que integran la organización."}'::jsonb, 0);
INSERT INTO public.page_sections (page_id, section_key, data, sort_order) VALUES ((SELECT id FROM public.pages WHERE slug = 'nosotros'), 'historia', '{"titulo":"Desde 2006, tejiendo un ciclo de valor."}'::jsonb, 0);
INSERT INTO public.nosotros_historia_filas (page_section_id, sort_order, ano, titulo, descripcion) VALUES
  ((SELECT id FROM public.page_sections WHERE page_id = (SELECT id FROM public.pages WHERE slug = 'nosotros') AND section_key = 'historia'), 0, '2006', 'Origen en Suba', 'Un grupo de recuperadores ambientales de Suba se organiza informalmente para dignificar su labor y avanzar hacia la formalización.'),
  ((SELECT id FROM public.page_sections WHERE page_id = (SELECT id FROM public.pages WHERE slug = 'nosotros') AND section_key = 'historia'), 1, '2013', 'Auto 275 y formalización', 'Se avanza en el proceso de formalización tras los autos de la Corte Constitucional que reconocen a los recuperadores como sujetos de especial protección.'),
  ((SELECT id FROM public.page_sections WHERE page_id = (SELECT id FROM public.pages WHERE slug = 'nosotros') AND section_key = 'historia'), 2, '2019', 'Nace ASOFRAIN E.S.P.', 'Denominación actual como Empresa de Servicios Públicos. Registro ante la SSPD y la UAESP. Se abre operación en Engativá y Usaquén.'),
  ((SELECT id FROM public.page_sections WHERE page_id = (SELECT id FROM public.pages WHERE slug = 'nosotros') AND section_key = 'historia'), 3, 'Hoy', '699.564 toneladas aprovechadas', '5 estaciones de clasificación (ECAs), servicio consolidado en tres localidades y un programa creciente de sensibilización territorial.');
INSERT INTO public.page_sections (page_id, section_key, data, sort_order) VALUES ((SELECT id FROM public.pages WHERE slug = 'nosotros'), 'mision', '{"descripcion":"Prestar el servicio público de aprovechamiento en Bogotá con excelencia técnica, dignificando a nuestros recuperadores ambientales y devolviendo valor a la ciudad y al medio ambiente."}'::jsonb, 0);
INSERT INTO public.page_sections (page_id, section_key, data, sort_order) VALUES ((SELECT id FROM public.pages WHERE slug = 'nosotros'), 'vision', '{"descripcion":"Ser referente nacional en aprovechamiento de residuos, con cobertura ampliada, tecnología de trazabilidad y un modelo replicable que consolide a Bogotá como una ciudad de economía circular."}'::jsonb, 0);
