  ((SELECT id FROM public.page_sections WHERE page_id = (SELECT id FROM public.pages WHERE slug = 'servicios') AND section_key = 'servicios'), 0, 'Recuperación de residuos aprovechables', 'Identificación, selección y recuperación en la fuente de materiales con potencial de aprovechamiento.'),
  ((SELECT id FROM public.page_sections WHERE page_id = (SELECT id FROM public.pages WHERE slug = 'servicios') AND section_key = 'servicios'), 1, 'Recolección selectiva', 'Rutas programadas puerta a puerta y por macrorruta, con horarios definidos por localidad.'),
