INSERT INTO public.page_sections (page_id, section_key, data, sort_order) VALUES ((SELECT id FROM public.pages WHERE slug = 'servicios'), 'tarifas_y_productos', '{"titulo":"Un marco tarifario público y regulado.","descripcion":"El servicio público de aprovechamiento está regulado por la Comisión de Regulación de Agua Potable y Saneamiento Básico (CRA) mediante la Resolución 720 de 2015. El valor se calcula por tonelada efectivamente aprovechada y se acredita a la factura del servicio de aseo. El usuario no paga extra por reciclar — al contrario, incentiva su tarifa.","cta_texto":"Ver normatividad completa →","cta_url":""}'::jsonb, 0);
